mapper.select:
select u.user_id, u.user_name, u.nick_name, u.dept_id, u.status, (select group_concat(distinct sp.post_name order by sp.post_sort, sp.post_name separator '、') from sys_user_post sup inner join sys_post sp on sp.post_id = sup.post_id and sp.status = '0' where sup.user_id = u.user_id) as post_names, d.dept_id, d.parent_id, d.ancestors, d.dept_name, d.status as dept_status from sys_user u left join sys_dept d on d.dept_id = u.dept_id where u.del_flag = '0'
and u.status = #{status}
and u.status = '0'
and u.user_name like concat('%', #{userName}, '%') and u.nick_name like concat('%', #{nickName}, '%')
and exists (select 1 from sys_user_post filter_up where filter_up.user_id = u.user_id and filter_up.post_id = #{postId})
and (u.user_name like concat('%', #{params.keyword}, '%') or u.nick_name like concat('%', #{params.keyword}, '%'))
and u.user_id != #{params.excludeUserId}
and (u.dept_id = #{params.salaryShopDeptId} or exists (select 1 from sys_user_shop sus where sus.user_id = u.user_id and sus.dept_id = #{params.salaryShopDeptId}))
${params.dataScope} order by u.nick_name, u.user_name, u.user_id limit #{params.limit}

select u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phonenumber, u.sex, u.status, u.del_flag, u.create_by, u.create_time, u.update_by, u.update_time, u.remark, d.dept_id, d.parent_id, d.ancestors, d.dept_name, d.order_num, d.leader, d.status as dept_status, p.profile_id, p.user_id as profile_user_id, p.employee_no, p.position_no, p.company_name, p.dept_level1_name, p.dept_level2_name, p.dept_level3_name, p.store_name, p.position_names, p.job_grade, p.department_supervisor, p.direct_supervisor, p.direct_supervisor_user_id, p.employee_status, p.employee_category, p.birth_date, p.id_type, p.id_number, p.blood_type, p.registered_residence, p.current_address, p.student_status, p.school_name, p.retirement_status, p.income_start_year_month, p.first_education, p.first_degree, p.first_graduation_date, p.first_graduation_school, p.first_major, p.highest_education, p.highest_degree, p.highest_graduation_date, p.highest_graduation_school, p.highest_major, p.political_status, p.marital_status, p.nationality, p.foreign_national_flag, p.ethnicity, p.health_status, p.emergency_contact, p.emergency_contact_relation, p.emergency_contact_phone, p.recruitment_channel, p.office_phone, p.work_start_date, p.work_years, p.entry_date, p.probation_period, p.planned_regularization_date, p.actual_regularization_date, p.company_years, p.current_position_start_date, p.contract_start_date, p.contract_end_date, p.contract_type, p.contract_term, p.renewal_count, p.work_location, p.work_city_level, p.attendance_method, p.household_type, p.social_type, p.social_security_location, p.housing_fund_location, p.leave_date, p.bank_name, p.bank_account, p.legal_entity, p.create_by as profile_create_by, p.create_time as profile_create_time, p.update_by as profile_update_by, p.update_time as profile_update_time from sys_user u left join sys_dept d on d.dept_id = u.dept_id left join sys_user_profile p on p.user_id = u.user_id where u.del_flag = '0' and u.user_id <> 1 and u.user_id = #{userId}
and (p.employee_status is null or p.employee_status <> '离职')
${params.dataScope} for update

select u.user_id, u.user_name, u.nick_name, u.phonenumber, u.status as account_status, u.dept_id, d.dept_name, coalesce(upc.post_names, profile_sp.post_name) as post_names, coalesce(main_sp.post_id, profile_sp.post_id) as post_id, coalesce(main_sp.post_code, profile_sp.post_code) as post_code, coalesce(main_sp.post_name, profile_sp.post_name) as post_name, p.employee_no, p.employee_status, p.id_type, p.id_number, p.current_address, p.student_status, p.school_name, p.retirement_status, p.income_start_year_month, p.job_grade, p.contract_type, p.contract_term, p.social_type, p.legal_entity, p.legal_entity_id, p.legal_entity_code, date_format(p.entry_date, '%Y-%m-%d') as entry_date, date_format(p.probation_start_date, '%Y-%m-%d') as probation_start_date, date_format(p.probation_end_date, '%Y-%m-%d') as probation_end_date, date_format(p.contract_start_date, '%Y-%m-%d') as contract_start_date, date_format(p.contract_end_date, '%Y-%m-%d') as contract_end_date, p.base_salary, p.post_salary, p.field_allowance, p.performance_salary, p.salary_total, p.salary_version from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_user_profile p on p.user_id = u.user_id left join ( select sup.user_id, group_concat(distinct sp.post_name order by sp.post_sort, sp.post_name separator '、') as post_names from sys_user_post sup inner join sys_post sp on sp.post_id = sup.post_id where sp.status = '0' group by sup.user_id ) upc on upc.user_id = u.user_id left join sys_user_post main_sup on main_sup.user_id = u.user_id and main_sup.post_id = ( select main_sup2.post_id from sys_user_post main_sup2 inner join sys_post main_sp2 on main_sp2.post_id = main_sup2.post_id where main_sup2.user_id = u.user_id and main_sp2.status = '0' order by main_sp2.post_sort asc, main_sp2.post_id asc limit 1 ) left join sys_post main_sp on main_sp.post_id = main_sup.post_id left join sys_post profile_sp on profile_sp.status = '0' and lower(profile_sp.post_code) collate utf8mb4_general_ci = lower(substring_index(p.position_no, '-', 1)) collate utf8mb4_general_ci where u.del_flag = '0'
and u.status = '0' and (p.employee_status is null or p.employee_status <> '离职')
AND EXISTS ( SELECT 1 FROM sys_user_post sign_sup INNER JOIN sys_post sp ON sp.post_id = sign_sup.post_id WHERE sign_sup.user_id = u.user_id AND sp.status = '0' AND sp.post_name = #{postName} )
AND ( u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE find_in_set(#{deptId}, ancestors) ) OR EXISTS ( SELECT 1 FROM sys_user_shop sus inner join sys_dept sd on sd.dept_id = sus.dept_id WHERE sus.user_id = u.user_id AND sd.del_flag = '0' AND sd.status = '0' AND ( sus.dept_id = #{deptId} OR find_in_set(#{deptId}, sd.ancestors) ) ) )
AND ( u.nick_name like concat('%', #{keyword}, '%') OR u.user_name like concat('%', #{keyword}, '%') OR u.phonenumber like concat('%', #{keyword}, '%') )
AND u.user_id in
#{candidateUserId}
AND u.phonenumber in
#{candidatePhone}
order by u.user_id limit #{limit}

select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.status, d.dept_id, d.parent_id, d.ancestors, d.dept_name, d.status as dept_status from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.nick_name like concat('%', #{nickName}, '%')
${params.dataScope}

select u.user_id, u.dept_id, as user_name, u.nick_name, as phonenumber, d.dept_name, u.status from sys_user u left join sys_dept d on d.dept_id = u.dept_id where u.del_flag = '0' and u.status = #{status} and u.user_name like concat('%', #{userName}, '%') and u.nick_name like concat('%', #{nickName}, '%') and u.phonenumber like concat('%', #{phonenumber}, '%')
and (u.dept_id = #{params.salaryShopDeptId} or exists (select 1 from sys_user_shop ss where ss.user_id = u.user_id and ss.dept_id = #{params.salaryShopDeptId}))
${params.dataScope}

select u.user_id, u.dept_id, u.user_name, u.nick_name, u.phonenumber, u.status, u.del_flag,
       d.dept_name,
       p.profile_id, p.user_id as profile_user_id, p.employee_no, p.position_no, p.id_number, p.employee_status,
       p.direct_supervisor_user_id
from sys_user u
join sys_dept d on d.dept_id = u.dept_id
left join sys_user_profile p on p.user_id = u.user_id
where u.del_flag = '0'


		and (

				or u.phonenumber = #{phone}
				or p.id_number = #{idNumber}
				or p.employee_no = #{employeeNo}

		)

	and 1 = 0

${query.params.dataScope}
order by u.user_id

select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.phonenumber, u.status, u.del_flag,
       d.dept_name, p.profile_id, p.user_id as profile_user_id, p.employee_no, p.position_no, p.id_number, p.employee_status
from sys_user u join sys_dept d on d.dept_id=u.dept_id
left join sys_user_profile p on p.user_id=u.user_id
where u.del_flag='0' and (


    or u.phonenumber=#{identity.phoneNumber}
    or p.id_number=#{identity.idNumber}
    or p.employee_no=#{identity.employeeNo}

)
${query.params.dataScope}
order by u.user_id

select u.user_id, u.dept_id, u.user_name, u.nick_name, u.phonenumber, u.sex, u.status, u.del_flag, u.create_by, u.create_time, u.update_by, u.update_time, u.remark, d.dept_id, d.parent_id, d.ancestors, d.dept_name, d.order_num, d.leader, d.status as dept_status, p.profile_id, p.user_id as profile_user_id, p.employee_no, p.position_no, p.company_name, p.dept_level1_name, p.dept_level2_name, p.dept_level3_name, p.store_name, p.position_names, p.job_grade, p.department_supervisor, p.direct_supervisor, p.direct_supervisor_user_id, p.employee_status, p.employee_category, p.birth_date, p.id_type, p.id_number, p.blood_type, p.registered_residence, p.current_address, p.student_status, p.school_name, p.retirement_status, p.income_start_year_month, p.first_education, p.first_degree, p.first_graduation_date, p.first_graduation_school, p.first_major, p.highest_education, p.highest_degree, p.highest_graduation_date, p.highest_graduation_school, p.highest_major, p.political_status, p.marital_status, p.nationality, p.foreign_national_flag, p.ethnicity, p.health_status, p.emergency_contact, p.emergency_contact_relation, p.emergency_contact_phone, p.recruitment_channel, p.office_phone, p.work_start_date, p.work_years, p.entry_date, p.probation_period, p.planned_regularization_date, p.actual_regularization_date, p.company_years, p.current_position_start_date, p.contract_start_date, p.contract_end_date, p.contract_type, p.contract_term, p.renewal_count, p.work_location, p.work_city_level, p.attendance_method, p.household_type, p.social_type, p.social_security_location, p.housing_fund_location, p.leave_date, p.bank_name, p.bank_account, p.legal_entity, p.create_by as profile_create_by, p.create_time as profile_create_time, p.update_by as profile_update_by, p.update_time as profile_update_time from sys_user u join sys_dept d on d.dept_id = u.dept_id left join sys_user_profile p on p.user_id = u.user_id where u.user_id = #{userId} and u.del_flag = '0'
and (
or u.phonenumber = #{phone} or p.id_number = #{idNumber} or p.employee_no = #{employeeNo}
)
and 1 = 0
${query.params.dataScope} for update

